css:
.d-copy-code-block{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-copy-code-block *,.d-copy-code-block *::before,.d-copy-code-block *::after{box-sizing:border-box}
.d-copy-code-block [hidden]{display:none!important}
.d-copy-code-block .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-copy-code-block .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-copy-code-block label{display:block;margin:8px 0}
.d-copy-code-block input,.d-copy-code-block select,.d-copy-code-block textarea,.d-copy-code-block button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-copy-code-block input:not([type=checkbox]):not([type=radio]),.d-copy-code-block select,.d-copy-code-block textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-copy-code-block button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-copy-code-block button:disabled{opacity:.5;cursor:default}
.d-copy-code-block :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-copy-code-block [aria-invalid=true]{border-color:var(--warn)!important}
.d-copy-code-block .d-scroll{max-width:100%;overflow:auto}
.d-copy-code-block table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-copy-code-block th,.d-copy-code-block td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-copy-code-block caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-copy-code-block progress{width:100%;accent-color:var(--ink)}
.d-copy-code-block pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-copy-code-block h3,.d-copy-code-block p{margin:8px 0}
.d-copy-code-block [aria-pressed=true],.d-copy-code-block [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-copy-code-block .d-grow{flex:1;min-width:100px}
.d-copy-code-block summary{cursor:pointer;padding:6px 0}
.d-copy-code-block ul,.d-copy-code-block ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-copy]').onclick=async()=>{const text=q('[data-code]').textContent;try{await navigator.clipboard.writeText(text);q('[data-fallback]').hidden=true;say('代码已复制，不含行号');}catch{q('[data-fallback]').hidden=false;q('[data-text]').value=text;q('[data-text]').focus();q('[data-text]').select();say('自动复制不可用，请复制已选中的代码');}};})(root, q, qa, say);
}
